using Microsoft.EntityFrameworkCore;using SmartFarm.Repositories.Data;using SmartFarm.Repositories.Entities;using SmartFarm.Services.Models;
namespace SmartFarm.Services.Services;
public sealed class TelemetryService(AppDbContext db)
{
    private static readonly TimeSpan StaleAfter=TimeSpan.FromMinutes(5);
    public async Task<TelemetryResponse> IngestAsync(TelemetryIngestRequest r)
    {var existing=await db.SensorTelemetry.AsNoTracking().Include(x=>x.Device).FirstOrDefaultAsync(x=>x.MessageId==r.MessageId.Trim());if(existing is not null)return ToDto(existing);var device=await db.IoTDevices.FirstOrDefaultAsync(x=>x.DeviceCode==r.DeviceCode.Trim())??throw new AppException(404,"IoT device not found.");if(device.Status==DeviceStatuses.Inactive)throw new AppException(409,"Inactive device cannot send telemetry.");var assignment=await db.TrayDevices.FirstOrDefaultAsync(x=>x.DeviceId==device.DeviceId&&x.IsActive)??throw new AppException(409,"Device is not assigned to an active soil tray.");Validate(r);var at=r.RecordedAt==default?DateTime.UtcNow:r.RecordedAt.ToUniversalTime();if(at>DateTime.UtcNow.AddMinutes(2)||at<DateTime.UtcNow.AddDays(-7))throw new AppException(400,"RecordedAt is outside the accepted range.");var item=new SensorTelemetry{MessageId=r.MessageId.Trim(),DeviceId=device.DeviceId,Device=device,SoilTrayId=assignment.SoilTrayId,Temperature=r.Temperature,AirHumidity=r.AirHumidity,SoilHumidity=r.SoilHumidity,LightIntensity=r.LightIntensity,FanState=r.FanState,LedState=r.LedState,PumpState=r.PumpState,RecordedAt=at};device.LastSeen=DateTime.UtcNow;device.Status=DeviceStatuses.Online;db.Add(item);await db.SaveChangesAsync();return ToDto(item);}
    public async Task HeartbeatAsync(string deviceCode,DateTime? at=null){var device=await db.IoTDevices.FirstOrDefaultAsync(x=>x.DeviceCode==deviceCode)??throw new AppException(404,"IoT device not found.");if(device.Status==DeviceStatuses.Inactive)throw new AppException(409,"Inactive device cannot send heartbeat.");device.LastSeen=(at??DateTime.UtcNow).ToUniversalTime();device.Status=DeviceStatuses.Online;await db.SaveChangesAsync();}
    public async Task<TelemetryResponse> LatestStaffAsync(int trayId)=>ToDto(await Query().Where(x=>x.SoilTrayId==trayId).OrderByDescending(x=>x.RecordedAt).FirstOrDefaultAsync()??throw new AppException(404,"Telemetry not found."));
    public async Task<PagedResponse<object>> HistoryStaffAsync(int trayId,QueryRequest request,DateTime? from,DateTime? to)=>await HistoryAsync(Query().Where(x=>x.SoilTrayId==trayId),request,from,to);
    public async Task<TelemetryResponse> LatestCustomerAsync(int customerId,int rentalId){var rental=await OwnedRental(customerId,rentalId);return await LatestStaffAsync(rental.SoilTrayId);}
    public async Task<PagedResponse<object>> HistoryCustomerAsync(int customerId,int rentalId,QueryRequest request,DateTime? from,DateTime? to){var rental=await OwnedRental(customerId,rentalId);return await HistoryStaffAsync(rental.SoilTrayId,request,from,to);}
    private async Task<PagedResponse<object>> HistoryAsync(IQueryable<SensorTelemetry> q,QueryRequest r,DateTime? from,DateTime? to){if(from.HasValue&&to.HasValue&&from>to)throw new AppException(400,"From must be before to.");if(from.HasValue)q=q.Where(x=>x.RecordedAt>=from.Value.ToUniversalTime());if(to.HasValue)q=q.Where(x=>x.RecordedAt<=to.Value.ToUniversalTime());var(page,size)=QueryHelper.Paging(r);var total=await q.CountAsync();var rows=await q.OrderByDescending(x=>x.RecordedAt).Skip((page-1)*size).Take(size).ToListAsync();return new(rows.Select(x=>(object)ToDto(x)).ToList(),page,size,total);}
    private async Task<TrayRental> OwnedRental(int userId,int id)=>await db.TrayRentals.AsNoTracking().FirstOrDefaultAsync(x=>x.RentalId==id&&x.CustomerId==userId)??throw new AppException(404,"Rental not found.");
    private IQueryable<SensorTelemetry> Query()=>db.SensorTelemetry.AsNoTracking().Include(x=>x.Device);
    private static void Validate(TelemetryIngestRequest r){if(r.Temperature is < -20 or > 80)throw new AppException(400,"Temperature is out of range.");if(r.AirHumidity is < 0 or > 100||r.SoilHumidity is < 0 or > 100)throw new AppException(400,"Humidity is out of range.");if(r.LightIntensity is < 0)throw new AppException(400,"Light intensity cannot be negative.");if(r.Temperature is null&&r.AirHumidity is null&&r.SoilHumidity is null&&r.LightIntensity is null)throw new AppException(400,"At least one sensor value is required.");}
    private static TelemetryResponse ToDto(SensorTelemetry x)=>new(x.TelemetryId,x.MessageId,x.DeviceId,x.Device?.DeviceCode??"",x.SoilTrayId,x.Temperature,x.AirHumidity,x.SoilHumidity,x.LightIntensity,x.FanState,x.LedState,x.PumpState,x.RecordedAt,DateTime.UtcNow-x.RecordedAt>StaleAfter);
}
